{"explanation":"With $1 at 100% annual interest compounded $n$ times per year, the balance after one year is $\left(1+\frac1n\right)^n$. As $n$ grows without bound, this approaches the number $e\approx2.71828$, so continuously compounded interest turns $1 into $e$ after one year.","manimCode":"const ax = new Axes({
  xRange: [0, 40, 5],
  yRange: [0, 3.1, 0.5],
  xLength: 9.5,
  yLength: 4.5,
  tips: true
});
ax.moveTo([0, -0.45, 0]);

const curve = ax.plot(x => Math.pow(1 + 1 / x, x), {
  color: BLUE,
  xRange: [1, 40],
  numSamples: 400
});

const eLevel = new Polygon({
  vertices: [ax.c2p(1, Math.E), ax.c2p(40, Math.E)],
  color: YELLOW
});
eLevel.setStrokeWidth(2).setFillOpacity(0);

const title = new Text({ text: 'More frequent compounding', color: WHITE, fontSize: 30 });
title.moveTo([0, 3.35, 0]);

const formula = new MathTex({ latex: 'A_n=\\left(1+\\frac{1}{n}\\right)^n' });
await formula.waitForRender();
formula.setColor(BLUE);
formula.moveTo([-3.7, 2.65, 0]);

const limitLabel = new MathTex({ latex: 'e\\approx2.71828' });
await limitLabel.waitForRender();
limitLabel.setColor(YELLOW);
limitLabel.moveTo([4.2, 2.05, 0]);

let n = 1;
let amount = Math.pow(1 + 1 / n, n);
const marker = new Dot({ point: ax.c2p(n, amount), color: ORANGE });
const guide = new Polygon({
  vertices: [ax.c2p(n, 0), ax.c2p(n, amount)],
  color: ORANGE
});
guide.setStrokeWidth(2).setFillOpacity(0);

let readout = new Text({
  text: 'n = 1     balance = $2.00000',
  color: ORANGE,
  fontSize: 24
});
readout.moveTo([0, -3.25, 0]);

scene.add(ax, title, formula, limitLabel, eLevel, curve, guide, marker, readout);
await scene.play(new AnimationGroup([new Create(curve), new Create(eLevel), new FadeIn(marker)]));

function updateReadout() {
  scene.remove(readout);
  readout = new Text({
    text: 'n = ' + n + '     balance = $' + amount.toFixed(5),
    color: ORANGE,
    fontSize: 24
  });
  readout.moveTo([0, -3.25, 0]);
  scene.add(readout);
}

const controls = new Controls(scene, { position: 'top-right', theme: 'dark', width: 250 });
controls.addSlider({
  label: 'Compounding periods (n)',
  min: 1,
  max: 40,
  value: 1,
  step: 1,
  onChange: value => {
    n = Math.round(value);
    amount = Math.pow(1 + 1 / n, n);
    marker.moveTo(ax.c2p(n, amount));
    guide.setVertices([ax.c2p(n, 0), ax.c2p(n, amount)]);
    updateReadout();
  }
});
controls.addButton({
  label: 'Reset to yearly',
  onClick: () => {
    n = 1;
    amount = 2;
    marker.moveTo(ax.c2p(n, amount));
    guide.setVertices([ax.c2p(n, 0), ax.c2p(n, amount)]);
    updateReadout();
  }
});

await scene.wait(999999);"}

